/**
 * And what is on the other arm, the same way.
 *
 * A separate table because a shield is not a weapon: it is worn by whoever has
 * an arm spare rather than by whoever fights a particular way, and the two
 * lists have nothing to say to each other. The shields carry no class colour —
 * see the packer — so one row of them serves every class that picks it up.
 */
export const LPC_GUARD: Record<string, [number, number][]> = {
  // heater, crusader, scutum, spartan, plus, two_engrailed
  'warrior-protection': [[35, 36], [31, 32], [43, 44], [47, 48], [39, 40], [51, 52]],
  // heater, crusader, scutum, spartan, plus, two_engrailed
  'paladin-protection': [[35, 36], [31, 32], [43, 44], [47, 48], [39, 40], [51, 52]],
  // heater, crusader, scutum, spartan, plus, two_engrailed
  'paladin-holy': [[37, 38], [33, 34], [45, 46], [49, 50], [41, 42], [53, 54]],
}

/**
 * The second of a pair, in the same order as `LPC_ARMS` so that one number
 * picks both.
 *
 * Empty on the action block, on purpose: a body in this set swings one arm,
 * and the blade in the other one is put away for the four tenths of a second
 * that takes rather than left hanging off an arm that did not move.
 */
export const LPC_OFF: Record<string, [number, number][]> = {
  'rogue-assassination': [[93, 94], [95, 96], [97, 98]],
}

